import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Configuration Reference — Apple","description":"Every Apple theme setting documented — keys, types, defaults, ranges, what they change and common mistakes, plus the conf.yml manifest and CSS token reference.","frontmatter":{"title":"Configuration Reference — Apple","description":"Every Apple theme setting documented — keys, types, defaults, ranges, what they change and common mistakes, plus the conf.yml manifest and CSS token reference."},"headers":[],"relativePath":"apple/configuration/reference.md","filePath":"apple/configuration/reference.md","lastUpdated":1785521346000}'),r={name:"apple/configuration/reference.md"};function c(s,e,n,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Every value Apple reads, its default, and when to change it. Settings are stored as <code>apple::&lt;key&gt;</code> rows in the panel <code>settings</code> table and edited from <strong>Admin → Apple Theme</strong> (Blueprint). There is no YAML config file.</p><h2 id="theme-settings" tabindex="-1">Theme settings <a class="header-anchor" href="#theme-settings" aria-label="Permalink to &quot;Theme settings&quot;">​</a></h2><h3 id="mode-default" tabindex="-1"><code>mode_default</code> <a class="header-anchor" href="#mode-default" aria-label="Permalink to &quot;`mode_default`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td><code>system</code> · <code>dark</code> · <code>light</code></td></tr><tr><td>Default</td><td><code>system</code></td></tr><tr><td>Stored as</td><td><code>apple::mode_default</code></td></tr></tbody></table><p>The mode used until someone picks one with the top-bar toggle. <code>system</code> follows the visitor&#39;s OS preference (<code>prefers-color-scheme</code>, defaulting to dark when unknown). A user&#39;s manual choice is stored in their browser (<code>localStorage: apple-mode</code>) and always wins over this default.</p><p><strong>Change it when:</strong> your brand is dark-first and you want first-time visitors to land in dark regardless of their OS.</p><p><strong>Common mistake:</strong> assuming this forces the mode. It is only the default — the per-browser toggle always overrides it.</p><hr><h3 id="accent" tabindex="-1"><code>accent</code> <a class="header-anchor" href="#accent" aria-label="Permalink to &quot;`accent`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td>one of 12 Catppuccin accents</td></tr><tr><td>Default</td><td><code>sapphire</code></td></tr><tr><td>Stored as</td><td><code>apple::accent</code></td></tr></tbody></table><p>The single accent color used for selection, primary actions, focus rings and the active sidebar icon. One value covers both modes — each accent has an official Mocha (dark) and Latte (light) hex:</p><table tabindex="0"><thead><tr><th>Accent</th><th>Dark (Mocha)</th><th>Light (Latte)</th></tr></thead><tbody><tr><td><code>blue</code></td><td><code>#89b4fa</code></td><td><code>#1e66f5</code></td></tr><tr><td><code>sapphire</code></td><td><code>#74c7ec</code></td><td><code>#209fb5</code></td></tr><tr><td><code>sky</code></td><td><code>#89dceb</code></td><td><code>#04a5e5</code></td></tr><tr><td><code>teal</code></td><td><code>#94e2d5</code></td><td><code>#179299</code></td></tr><tr><td><code>green</code></td><td><code>#a6e3a1</code></td><td><code>#40a02b</code></td></tr><tr><td><code>yellow</code></td><td><code>#f9e2af</code></td><td><code>#df8e1d</code></td></tr><tr><td><code>peach</code></td><td><code>#fab387</code></td><td><code>#fe640b</code></td></tr><tr><td><code>red</code></td><td><code>#f38ba8</code></td><td><code>#d20f39</code></td></tr><tr><td><code>pink</code></td><td><code>#f5c2e7</code></td><td><code>#ea76cb</code></td></tr><tr><td><code>mauve</code></td><td><code>#cba6f7</code></td><td><code>#8839ef</code></td></tr><tr><td><code>lavender</code></td><td><code>#b4befe</code></td><td><code>#7287fd</code></td></tr><tr><td><code>flamingo</code></td><td><code>#f2cdcd</code></td><td><code>#dd7878</code></td></tr></tbody></table><p>In dark mode filled primary buttons use the accent with near-black text; in light mode the accent is deepened (<code>65% accent + black</code>) so white text keeps ≥ 4.5:1 contrast. You never need to handle this — it is computed.</p><p><strong>Change it when:</strong> matching a brand color. Sapphire and sky read most &quot;iOS&quot;; mauve/lavender are the loudest options.</p><p><strong>Common mistake:</strong> none really — invalid values fall back to <code>sapphire</code> server-side.</p><hr><h3 id="glass-blur" tabindex="-1"><code>glass_blur</code> <a class="header-anchor" href="#glass-blur" aria-label="Permalink to &quot;`glass_blur`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td>integer <code>0–30</code> (px)</td></tr><tr><td>Default</td><td><code>18</code></td></tr><tr><td>Stored as</td><td><code>apple::glass_blur</code></td></tr></tbody></table><p>Backdrop blur behind the sidebar, top bar and cards. Lower values read more matte and cost less GPU on weak machines; <code>0</code> disables frosted glass entirely (surfaces become translucent tints).</p><p><strong>Change it when:</strong> you want a flatter, more matte look (try <code>8–12</code>), or a stronger frost (try <code>24–30</code>).</p><p><strong>Common mistake:</strong> cranking blur up <em>and</em> opacity down together — text over busy backgrounds can drop below readable contrast. Raise opacity instead.</p><hr><h3 id="glass-opacity" tabindex="-1"><code>glass_opacity</code> <a class="header-anchor" href="#glass-opacity" aria-label="Permalink to &quot;`glass_opacity`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td>integer <code>50–95</code> (%)</td></tr><tr><td>Default</td><td><code>72</code></td></tr><tr><td>Stored as</td><td><code>apple::glass_opacity</code></td></tr></tbody></table><p>How solid frosted surfaces are. This modifies surface <strong>alpha only, never hue</strong> — the theme&#39;s &quot;matte&quot; character comes from high opacity + moderate blur. Higher is more solid; lower is more see-through.</p><p><strong>Change it when:</strong> lowering blur (raise opacity to compensate) or when the page background shows through too much.</p><hr><h3 id="radius" tabindex="-1"><code>radius</code> <a class="header-anchor" href="#radius" aria-label="Permalink to &quot;`radius`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td>integer <code>10–22</code> (px)</td></tr><tr><td>Default</td><td><code>16</code></td></tr><tr><td>Stored as</td><td><code>apple::radius</code></td></tr></tbody></table><p>Corner radius for cards and containers. Buttons, inputs and nav rows automatically stay a step squarer (<code>radius − 6px</code>), modals a step rounder (<code>+ 2px</code>) — one value drives the whole shape scale.</p><p><strong>Change it when:</strong> you want a squarer, more utilitarian feel (<code>10–12</code>) or maximum iOS softness (<code>20–22</code>).</p><hr><h3 id="sidebar-rail" tabindex="-1"><code>sidebar_rail</code> <a class="header-anchor" href="#sidebar-rail" aria-label="Permalink to &quot;`sidebar_rail`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td>switch <code>0</code> / <code>1</code></td></tr><tr><td>Default</td><td><code>0</code> (expanded)</td></tr><tr><td>Stored as</td><td><code>apple::sidebar_rail</code></td></tr></tbody></table><p>Whether the sidebar starts collapsed to a 76px icon rail. Anyone can expand it with the sidebar footer toggle; their choice persists in their browser (<code>localStorage: apple-rail</code>) and wins over this default. On mobile (≤ 992px) the rail is ignored — the drawer always shows labels.</p><hr><h3 id="animations" tabindex="-1"><code>animations</code> <a class="header-anchor" href="#animations" aria-label="Permalink to &quot;`animations`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td>switch <code>0</code> / <code>1</code></td></tr><tr><td>Default</td><td><code>1</code> (on)</td></tr><tr><td>Stored as</td><td><code>apple::animations</code></td></tr></tbody></table><p>Interface transitions (150–250ms, ease-out). Off makes everything effectively instant. <code>prefers-reduced-motion: reduce</code> is <strong>always</strong> respected regardless of this setting — you cannot force motion on users who opted out.</p><hr><h3 id="dashboard-custom" tabindex="-1"><code>dashboard_custom</code> <a class="header-anchor" href="#dashboard-custom" aria-label="Permalink to &quot;`dashboard_custom`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Type</td><td>switch <code>0</code> / <code>1</code></td></tr><tr><td>Default</td><td><code>1</code> (bento)</td></tr><tr><td>Stored as</td><td><code>apple::dashboard_custom</code></td></tr></tbody></table><p>Whether the admin home page renders Apple&#39;s bento grid. Off renders the stock Pterodactyl dashboard markup, which ships inside the same patched view as a runtime fallback — no reinstall needed to flip this.</p><div class="info custom-block"><p class="custom-block-title">Serialization note</p><p>Blueprint&#39;s settings library serializes values (<code>s:1:&quot;1&quot;;</code>). Apple&#39;s runtime unwraps this everywhere it reads the table directly (dashboard view, standalone wrapper), so toggles behave correctly in both variants.</p></div><hr><h3 id="init-system" tabindex="-1"><code>init</code> (system) <a class="header-anchor" href="#init-system" aria-label="Permalink to &quot;`init` (system)&quot;">​</a></h3><p>Version marker written on every hub load. Never accepted from input; safe to ignore.</p><hr><h2 id="conf-yml-manifest-blueprint" tabindex="-1"><code>conf.yml</code> manifest (Blueprint) <a class="header-anchor" href="#conf-yml-manifest-blueprint" aria-label="Permalink to &quot;`conf.yml` manifest (Blueprint)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>YAML path</th><th>Value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>info.name</code></td><td><code>Apple</code></td><td>Display name</td></tr><tr><td><code>info.identifier</code></td><td><code>apple</code></td><td>Unique ID (lowercase, no hyphens)</td></tr><tr><td><code>info.version</code></td><td><code>1.0.0</code></td><td>SemVer</td></tr><tr><td><code>info.target</code></td><td><code>beta-2026-05</code></td><td>Blueprint build target</td></tr><tr><td><code>info.author</code></td><td><code>Pingless.org (AnAverageBeing)</code></td><td>Author</td></tr><tr><td><code>info.icon</code></td><td><code>icon.svg</code></td><td>Extension list icon</td></tr><tr><td><code>admin.view</code></td><td><code>admin/view.blade.php</code></td><td>Settings hub partial</td></tr><tr><td><code>admin.controller</code></td><td><code>admin/controller.php</code></td><td>Settings hub controller</td></tr><tr><td><code>admin.wrapper</code></td><td><code>admin/wrapper.blade.php</code></td><td>Rendered on <strong>every</strong> admin page — the theme&#39;s only entry point</td></tr><tr><td><code>dashboard.wrapper</code></td><td><code>&quot;&quot;</code></td><td>Unused (admin-only theme)</td></tr><tr><td><code>data.directory</code></td><td><code>private</code></td><td>Install/remove hooks</td></tr><tr><td><code>data.public</code></td><td><code>public</code></td><td>Assets → <code>public/extensions/apple</code></td></tr><tr><td><code>requests.views</code></td><td><code>src/views</code></td><td>Blade partials (<code>variables</code>, <code>dashboard</code>)</td></tr></tbody></table><hr><h2 id="css-custom-properties-for-extension-authors" tabindex="-1">CSS custom properties (for extension authors) <a class="header-anchor" href="#css-custom-properties-for-extension-authors" aria-label="Permalink to &quot;CSS custom properties (for extension authors)&quot;">​</a></h2><p>All values land in <code>--ap-*</code> variables on <code>&lt;html&gt;</code>; the active mode is <code>html[data-apple=&quot;dark&quot;|&quot;light&quot;]</code>. If you build admin UI for an extension, consuming these keeps you visually native:</p><table tabindex="0"><thead><tr><th>Token group</th><th>Variables</th></tr></thead><tbody><tr><td>Surfaces</td><td><code>--ap-base</code> <code>--ap-mantle</code> <code>--ap-crust</code> <code>--ap-surface0/1/2</code></td></tr><tr><td>Text</td><td><code>--ap-text</code> <code>--ap-subtext0</code> <code>--ap-subtext1</code> <code>--ap-overlay0/1</code></td></tr><tr><td>Accent</td><td><code>--ap-accent</code> <code>--ap-accent-strong</code> <code>--ap-on-accent</code> <code>--ap-active</code> <code>--ap-ring</code></td></tr><tr><td>Semantic</td><td><code>--ap-green</code> <code>--ap-yellow</code> <code>--ap-red</code> <code>--ap-info</code></td></tr><tr><td>Structure</td><td><code>--ap-card</code> <code>--ap-fill</code> <code>--ap-hairline</code> <code>--ap-hover</code> <code>--ap-radius</code> <code>--ap-radius-sm</code> <code>--ap-radius-lg</code></td></tr><tr><td>Behavior</td><td><code>--ap-glass-blur</code> <code>--ap-glass-opacity</code> <code>--ap-ease</code> <code>--ap-dur</code> <code>--ap-z-*</code></td></tr><tr><td>Type</td><td><code>--ap-font</code> <code>--ap-mono</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Do not hardcode palette hexes in your extension</p><p>Values like <code>#1e1e2e</code> or <code>#74c7ec</code> change with the admin&#39;s accent choice and the light/dark toggle. Always consume the variables — <code>var(--ap-accent)</code>, <code>var(--ap-text)</code> — so your UI follows the theme.</p></div>',56)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
